"""Replay the position ratio on the public practice partitions and transparent controls."""
from collections import defaultdict
import json
from pathlib import Path
from random import Random
from statistics import median
import sys

from vs import corpus, dsl


def group_toks(pages):
    groups=defaultdict(list)
    for t in dsl.tokens(pages):
        groups[t['line']].append(t)
    return groups


def flags_from_groups(groups, line_range=None, clear_only=False):
    flagged = []
    for group in groups.values():
        counted = group[0]['unit']=='P'
        if line_range is not None:
            counted &= line_range[0] <= group[0]['n'] <= line_range[1]
        # The null shuffles among every token on a line before selecting by certainty and position.
        values = [None if dsl.UNCERTAIN(t['w']) else int(1<=len(dsl.SEG(t['w']))<=3) for t in group]
        if clear_only and None in values:
            counted = False
        flagged.append((counted, values, tuple((t['k']==t['n']-1, 0<t['k']<t['n']-1) for t in group)))
    return flagged


def rates(rows):
    end_hits=end_n=mid_hits=mid_n=0
    for counted,flags,positions in rows:
        if not counted:
            continue
        for flag,(line_final,mid_line) in zip(flags,positions,strict=True):
            if flag is None:
                continue
            if line_final:
                end_n+=1; end_hits+=flag
            if mid_line:
                mid_n+=1; mid_hits+=flag
    a=end_hits/end_n
    b=mid_hits/mid_n
    return {'value':a/b, 'final': {'hits':end_hits,'words':end_n}, 'interior':{'hits':mid_hits,'words':mid_n}}


def permute(rows,rng):
    for condition,flags,positions in rows:
        drawn=list(flags)
        rng.shuffle(drawn)
        yield condition,drawn,positions


def test(rows, permutations):
    observed=rates(rows)
    rng=Random(408)
    null=[rates(permute(rows,rng))['value'] for _ in range(permutations)]
    p=(1+sum(value>=observed['value'] for value in null))/(len(null)+1)
    return {**observed,'p_upper':p,'null_median':median(null),'perms':permutations,'pass':observed['value']>1 and p<=.01}


def synthetic_layout(rows, rng, mode):
    """Keep the number of positions and short-word opportunities in each row."""
    for condition,flags,positions in rows:
        values = [int(rng.random() < .22) if flag is None else flag for flag in flags]
        rng.shuffle(values)
        if condition and mode!='exchangeable' and len(values)>=3:
            # Put a long word first, when one exists. Treat the rest alike unless the terminal mechanism is active.
            if 0 in values:
                i=values.index(0)
                values[0],values[i]=values[i],values[0]
                if mode=='short_terminal' and rng.random()<.35 and 1 in values[1:]:
                    i=values.index(1,1)
                    values[-1],values[i]=values[i],values[-1]
        yield condition, values, positions


def main():
    work=Path(sys.argv[1])
    registration=json.loads((work/'fact-draft.json').read_text())
    out={}
    for edition in ('zl','it','rf'):
        out[edition]={}
        for part,pages in zip(('training','evaluation'),corpus.split_pages('practice',edition),strict=True):
            grouped=group_toks(pages)
            data=flags_from_groups(grouped)
            result=test(data,399)
            if edition=='zl' and part=='evaluation':
                official=dsl.evaluate(registration['spec'],pages)
                assert official['value']==round(result['value'],6)
                assert official['detail']['shuffle_within_line']['p']==round(result['p_upper'],4)
                assert official['pass']==result['pass']
            out[edition][part]={'primary':result}
            if part=='evaluation':
                out[edition][part]['sensitivity']={name:test(flags_from_groups(grouped,interval,clear),99)
                    for name,interval,clear in [('3–5 words',(3,5),False),('6 or more words',(6,999),False),('completely certain lines',None,True)]}
    _,pages=corpus.split_pages('practice')
    controls=flags_from_groups(group_toks(pages))
    out['synthetic']={mode:[test(list(synthetic_layout(controls,Random(722401+i),mode)),99) for i in range(16)]
                      for mode in ('exchangeable','long_initial','short_terminal')}
    print(json.dumps(out,indent=2))


if __name__=='__main__':
    main()

scripts.write_book.py:
"""Generate length-only writing controls without consulting manuscript word identities."""
from bisect import bisect_left
from collections import Counter
from itertools import accumulate
from math import ceil
from random import Random
from pathlib import Path
import json
import sys

from vs import corpus, ivtff


def fit(train):
    word_lengths=Counter()
    ordinary,ends=[],[]
    for page in train:
        for line in page.lines:
            if line.unit!='P' or not line.words:
                continue
            lengths=[len(ivtff.segment(w,'eva-basic')) for w in line.words if not ivtff.uncertain(w)]
            word_lengths.update(lengths)
            if len(lengths)==len(line.words):
                width=sum(lengths)+len(lengths)-1
                (ends if line.para_end else ordinary).append(width)
    ordinary.sort()
    capacity=ordinary[ceil(.75*len(ordinary))-1]
    return {'capacity':capacity,'ends':ends,'widths':[max(3,min(capacity,w)) for w in ends],
            'length_counts':dict(sorted(word_lengths.items())), 'ordinary_training_lines':len(ordinary)}


def shape(pages):
    return [[(line.unit,line.para_end,len(line.words)) for line in page.lines if line.words] for page in pages]


class Writer:
    def __init__(self, settings,seed):
        self.settings=settings
        self.stream=Random(seed)
        keys=sorted(int(k) for k in settings['length_counts'])
        self.lengths=keys
        self.weights=list(accumulate(settings['length_counts'][str(k)] for k in keys))
        self.pending=None

    def draw(self,max_length=None):
        if max_length is None:
            limit=len(self.lengths)
        else:
            limit=bisect_left(self.lengths,max_length+1)
        position=bisect_left(self.weights,self.stream.random()*self.weights[limit-1],0,limit)
        return self.lengths[position]

    def within_capacity(self,width):
        lengths=[]
        remaining=width+1
        minimum=self.lengths[0]+1
        while remaining>=minimum:
            new=self.draw(remaining-1)
            lengths.append(new)
            remaining-=new+1
        return lengths

    def greedy(self,width):
        lengths=[]
        remaining=width+1
        while True:
            new=self.pending if self.pending is not None else self.draw()
            self.pending=None
            if new+1<=remaining or not lengths:
                lengths.append(new)
                remaining-=new+1
            else:
                self.pending=new
                return lengths

    def token(self,length):
        return 'Z'+''.join(self.stream.choices('aodyeqklrnpm',k=length-1))

    def rows(self, page_shapes,mode):
        for page in page_shapes:
            self.pending=None
            for unit,para_end,slots in page:
                if unit!='P' or mode=='fixed_slots':
                    lengths=[self.draw() for _ in range(slots)]
                else:
                    width=self.stream.choice(self.settings['widths']) if para_end else self.settings['capacity']
                    lengths=self.within_capacity(width) if mode=='capacity_fit' else self.greedy(width)
                    if para_end:
                        self.pending=None
                yield [self.token(length) for length in lengths]


def main():
    work=Path(sys.argv[1]); train,_=corpus.split_pages('practice')
    cfg=fit(train)
    book=shape(corpus.pages())
    cfg['length_counts']={str(k):v for k,v in cfg['length_counts'].items()}
    (work/'frozen.json').write_text(json.dumps({'settings':cfg,'layout':book},indent=2)+'\n')
    primary=list(Writer(cfg,643701).rows(book,'capacity_fit'))
    assert all(len(ivtff.segment(w,'eva-basic'))==len(w) for line in primary for w in line)
    (work/'primary-lines.json').write_text(json.dumps(primary,separators=(',',':'))+'\n')
    print(json.dumps({'width':cfg['capacity'],'length_counts':cfg['length_counts'],'lines':len(primary),'words':sum(map(len,primary))}))


if __name__=='__main__':
    main()
